import { useEffect, useState } from "react";
import { toast } from "sonner";
import { Lightbulb, Send, Clock, Check, X as XIcon } from "lucide-react";
import NavBar from "@/components/NavBar";
import { Input } from "@/components/ui/input";
import { createSuggestion, listMySuggestions } from "@/lib/api";

const STATUS_META = {
  open: { label: "Pending", cls: "bg-[#ffe4d1] text-[#ff6a00]", Icon: Clock },
  done: { label: "Added", cls: "bg-green-100 text-green-700", Icon: Check },
  dismissed: { label: "Dismissed", cls: "bg-red-50 text-red-500", Icon: XIcon },
};

export default function SuggestPage() {
  const [name, setName] = useState("");
  const [notes, setNotes] = useState("");
  const [busy, setBusy] = useState(false);
  const [mine, setMine] = useState([]);
  const [loading, setLoading] = useState(true);

  const refresh = async () => {
    try {
      const data = await listMySuggestions();
      setMine(data);
    } catch {
      toast.error("Could not load your suggestions.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    refresh();
  }, []);

  const onSubmit = async (e) => {
    e.preventDefault();
    if (!name.trim()) return;
    setBusy(true);
    try {
      await createSuggestion(name.trim(), notes.trim());
      toast.success("Sent to CarterB");
      setName("");
      setNotes("");
      refresh();
    } catch (e) {
      const msg = e?.response?.data?.detail || "Could not submit suggestion";
      toast.error(typeof msg === "string" ? msg : "Could not submit suggestion");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#fff7f0]">
      <NavBar />
      <main className="max-w-3xl mx-auto px-5 sm:px-8 py-10">
        <div className="flex items-center gap-2 mb-2">
          <span className="grid place-items-center w-9 h-9 rounded-xl bg-[#ff6a00] text-white">
            <Lightbulb size={18} />
          </span>
          <h1 className="font-display text-3xl sm:text-4xl font-extrabold tracking-tight">
            Suggest a game
          </h1>
        </div>
        <p className="text-[#5c534d]">
          Missing a title? Drop it here — CarterB reviews every suggestion.
        </p>

        <form
          onSubmit={onSubmit}
          data-testid="suggest-form"
          className="mt-8 bg-white border border-[#efe3d6] rounded-2xl p-5 sm:p-6 space-y-4"
        >
          <label className="block">
            <span className="text-xs font-semibold uppercase tracking-widest text-[#5c534d]">
              Game name
            </span>
            <Input
              data-testid="suggest-name-input"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g. Slither.io"
              maxLength={120}
              required
              className="mt-1 h-12 bg-white border-[#efe3d6] rounded-xl focus-visible:ring-2 focus-visible:ring-[#ff6a00] focus-visible:ring-offset-0 focus-visible:border-[#ff6a00]"
            />
          </label>
          <label className="block">
            <span className="text-xs font-semibold uppercase tracking-widest text-[#5c534d]">
              Notes (optional)
            </span>
            <textarea
              data-testid="suggest-notes-input"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="Where to find it, why you'd want it, link, etc."
              maxLength={1000}
              rows={4}
              className="mt-1 w-full rounded-xl border border-[#efe3d6] bg-white p-3 text-sm focus:outline-none focus:ring-2 focus:ring-[#ff6a00] focus:border-[#ff6a00]"
            />
          </label>
          <div className="flex items-center justify-between">
            <span className="text-xs text-[#5c534d]">
              {notes.length}/1000
            </span>
            <button
              type="submit"
              disabled={busy || !name.trim()}
              data-testid="suggest-submit-btn"
              className="inline-flex items-center gap-1.5 px-5 py-2.5 rounded-full bg-[#ff6a00] text-white text-sm font-semibold hover:bg-[#e85d00] disabled:opacity-60 transition-colors"
            >
              <Send size={14} /> {busy ? "Sending…" : "Send suggestion"}
            </button>
          </div>
        </form>

        <section className="mt-10">
          <h2 className="font-display font-bold text-lg tracking-tight mb-3">
            Your suggestions
          </h2>
          {loading ? (
            <p className="text-sm text-[#5c534d]">Loading…</p>
          ) : mine.length === 0 ? (
            <div
              data-testid="my-suggestions-empty"
              className="text-sm text-[#5c534d] italic bg-white border border-dashed border-[#efe3d6] rounded-2xl px-4 py-6 text-center"
            >
              You haven&apos;t suggested anything yet.
            </div>
          ) : (
            <ul
              data-testid="my-suggestions-list"
              className="bg-white border border-[#efe3d6] rounded-2xl divide-y divide-[#efe3d6] overflow-hidden"
            >
              {mine.map((s) => {
                const meta = STATUS_META[s.status] || STATUS_META.open;
                const { Icon } = meta;
                return (
                  <li key={s.id} className="px-4 py-3 flex items-start justify-between gap-3">
                    <div className="min-w-0">
                      <div className="font-semibold text-[#1a1613] truncate">
                        {s.game_name}
                      </div>
                      {s.notes && (
                        <div className="text-xs text-[#5c534d] mt-0.5 line-clamp-2">
                          {s.notes}
                        </div>
                      )}
                      <div className="text-[10px] text-[#5c534d] mt-1 uppercase tracking-widest">
                        {new Date(s.created_at).toLocaleDateString()}
                      </div>
                    </div>
                    <span
                      className={`inline-flex items-center gap-1 shrink-0 rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-widest ${meta.cls}`}
                    >
                      <Icon size={11} /> {meta.label}
                    </span>
                  </li>
                );
              })}
            </ul>
          )}
        </section>
      </main>
    </div>
  );
}
